import { logList } from "@/api/safeDanger/report";
export default {
  name: "typicalCaseWorkLog",
  props: {
    detailId: {
      type: String,
      require: false
    }
  },
  data() {
    return {
      // 查询参数
      queryParams: {
        currentPage: 1,
        size: 20,
        hiddenId: undefined,
      },
      // 总条数
      total: 0,
      // 已办列表表格数据
      activeLogList: [],
      // 弹出层标题
      title: "",
      //遮罩层
      loading: true
    }
  },
  created() {

  },
  mounted() {
    this.getList();
  },
  methods: {
    /** 查询已办列表 */
    getList() {
      this.loading = true;
      this.queryParams.hiddenId = this.detailId
      logList(this.queryParams).then(response => {
          this.activeLogList = response.data.records;
          this.total = response.data.total;
          this.loading = false;
        }
      );
    },

    //设置行样式
    rowStyle({row,rowIndex}) {
      let styleJson = {}
      if ("2" === row.currentState) {
        styleJson = {
          'color' : 'red'
        }
      }else {

      }
      return styleJson
    }
  }
}
